INSERT INTO periodo(numero,nome,ordem) VALUES(2,'2º período',2) ON CONFLICT(numero) DO NOTHING;
INSERT INTO disciplina(periodo_id,nome,slug,descricao,possui_prova) SELECT id,'Cálculo para Computação I','calculo_para_computacao_1','Unidade 1: funções e limites. Unidade 2: derivadas. Somente a prova da unidade 1 foi fornecida.',TRUE FROM periodo WHERE numero=2 ON CONFLICT(slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,descricao,ordem) SELECT id,'1ª unidade · Funções compostas','funcoes_compostas','Composição, ordem, domínio e decomposição.',1 FROM disciplina WHERE slug='calculo_para_computacao_1' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,descricao,ordem) SELECT id,'1ª unidade · Funções inversas','funcoes_inversas','Injetividade, sobrejetividade, bijetividade, inversa e gráficos.',2 FROM disciplina WHERE slug='calculo_para_computacao_1' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,descricao,ordem) SELECT id,'1ª unidade · Simplificação algébrica','simplificacao_algebrica','Fator comum, produtos notáveis, cancelamento e restrições do domínio.',3 FROM disciplina WHERE slug='calculo_para_computacao_1' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,descricao,ordem) SELECT id,'1ª unidade · Limites','limites','Conceito, propriedades, substituição, indeterminações, confronto, definição precisa e infinito.',4 FROM disciplina WHERE slug='calculo_para_computacao_1' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,descricao,ordem) SELECT id,'1ª unidade · Limites laterais e continuidade','continuidade','Limites laterais, funções por partes e continuidade no ponto.',5 FROM disciplina WHERE slug='calculo_para_computacao_1' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,descricao,ordem) SELECT id,'2ª unidade · Definição de derivada','derivada_definicao','Quociente incremental, reta tangente, taxa instantânea e derivabilidade.',6 FROM disciplina WHERE slug='calculo_para_computacao_1' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,descricao,ordem) SELECT id,'2ª unidade · Regras de derivação','regras_derivacao','Constante, potência, soma, produto, quociente, cadeia, trigonométricas, exponenciais, logaritmos e hiperbólicas.',7 FROM disciplina WHERE slug='calculo_para_computacao_1' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,descricao,ordem) SELECT id,'2ª unidade · Derivação implícita','derivacao_implicita','Derivação de relações e funções inversas.',8 FROM disciplina WHERE slug='calculo_para_computacao_1' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO assunto(disciplina_id,nome,slug,descricao,ordem) SELECT id,'2ª unidade · Aplicações da derivada','aplicacoes_derivada','Taxas de variação, crescimento e decaimento, taxas relacionadas, aproximação linear e diferenciais.',9 FROM disciplina WHERE slug='calculo_para_computacao_1' ON CONFLICT(disciplina_id,slug) DO NOTHING;
INSERT INTO material(disciplina_id,titulo,descricao,tipo,referencia_externa,fonte_monitor_virtual,disponivel_para_pratica,autorizacao_professor) SELECT d.id,'01 Função Composta e Inversa','Material de estudo; consulte as páginas originais para fórmulas e gráficos.','TRECHO_LIVRO','local:materiais_academicos/periodo_02/calculo_para_computacao_1/01 Função Composta e Inversa.pdf',TRUE,FALSE,FALSE FROM disciplina d WHERE slug='calculo_para_computacao_1' AND NOT EXISTS(SELECT 1 FROM material m WHERE m.disciplina_id=d.id AND m.referencia_externa='local:materiais_academicos/periodo_02/calculo_para_computacao_1/01 Função Composta e Inversa.pdf');
